import math

solutions = []

# Constraints: 2 <= n <= 5, 3 <= x <= 10, and x > n
for n in range(2, 6):
    for x in range(3, 11):
        if x <= n:
            continue  # Enforce x > n

        # Check the equation: x^n + x = 2^k + 2, which means x^n + x - 2 = 2^k
        lhs_minus_2 = x**n + x - 2

        # Check if lhs_minus_2 is a power of 2
        if lhs_minus_2 > 0 and (lhs_minus_2 & (lhs_minus_2 - 1) == 0):
            # It is a power of 2, calculate k
            k = int(math.log2(lhs_minus_2))
            solutions.append((x, n, k))
            print(f"Found solution: x={x}, n={n}, k={k}. Check: {x}^{n} + {x} = {x**n + x} = 2^{k} + 2 = {2**k + 2}")

if not solutions:
    print("No solutions found in the tested range.")
else:
    print(f"Total solutions found: {solutions}")

import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

def check_n_equals_4(x):
    # Constraints: x > 4 and x is not congruent to 1 mod 3
    if x <= 4 or x % 3 == 1:
        return None, None

    # Equation: x^4 + x = 2^k + 2  => x^4 + x - 2 = 2^k
    lhs = x**4 + x - 2

    if is_power_of_two(lhs):
        k = int(math.log2(lhs))

        # Since n=4 (even), k must be even for a solution to exist 
        # based on the derived modulo 3 constraints.
        if k % 2 == 0:
            return x, k
        else:
            return x, k # Found solution, but fails parity check

    return x, None

solutions = []
# Systematically check x up to 30
for x_val in range(5, 31):
    x, k = check_n_equals_4(x_val)
    if k is not None:
        solutions.append((x, k))

print("Systematic search for n=4 (x > 4, x % 3 != 1):")
print("Solutions found (x, k):")
if solutions:
    for s in solutions:
        print(f"  {s}")
else:
    print("  No solutions found in the tested range.")
